CREATE TEMPORARY VIEW exp_cheapest_step1_${grass_region_without_quote} as
SELECT a.local_hour
     ,exp_group_id
     ,is_item_card
     ,is_ads
     ,mapping_general
     ,b.shop_scs_type
     ,b.business_type
     ,sum(imp_cnt) item_imp_cnt
     ,sum(click_cnt) item_click_cnt
     ,sum(order_cnt) item_order_cnt
     ,sum(gmv) item_gmv
     ,sum(case when c.model_id is not null then order_cnt end) model_order_cnt
     ,sum(case when c.model_id is not null then gmv end) model_gmv
from traffic_exp_aggr_${grass_region_without_quote} a
