left join cheapest_model_list_${grass_region_without_quote} c
on a.local_hour = c.local_hour
and a.model_id = c.model_id
and b.business_type = c.business_type
group by 1,2,3,4,5,6,7
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW exp_cheapest_${grass_region_without_quote} as
SELECT local_hour
     ,exp_group_id
     ,if(grouping(is_item_card) = 1, '__ALL__', is_item_card) is_item_card
     ,if(grouping(is_ads) = 1, '__ALL__', is_ads) is_ads
     ,mapping_general
     ,shop_scs_type
     ,business_type
     ,sum(item_imp_cnt) item_imp_cnt
     ,sum(item_click_cnt) item_click_cnt
     ,sum(item_order_cnt) item_order_cnt
     ,sum(item_gmv) item_gmv
     ,sum(model_order_cnt) model_order_cnt
     ,sum(model_gmv) model_gmv
    from exp_cheapest_step1_${grass_region_without_quote}
group by
    GROUPING SETS (
       (local_hour,exp_group_id,is_item_card,is_ads,mapping_general,shop_scs_type,business_type),
       (local_hour,exp_group_id,is_ads,mapping_general,shop_scs_type,business_type),
       (local_hour,exp_group_id,is_item_card,mapping_general,shop_scs_type,business_type),
       (local_hour,exp_group_id,mapping_general,shop_scs_type,business_type)
    )
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW traffic_exp_cspu_${grass_region_without_quote} as
select a.local_hour
     ,exp_group_id
     ,if(grouping(is_item_card) = 1, '__ALL__', is_item_card) is_item_card
     ,if(grouping(is_ads) = 1, '__ALL__', is_ads) is_ads
     ,mapping_general
     ,sum(case when d.item_id is not null then imp_cnt else 0 end) winner_cspu_imp_cnt
     ,sum(case when e.item_id is not null then imp_cnt else 0 end) cheapest_cspu_imp_cnt
     ,sum(case when d.item_id is not null or e.item_id is not null then imp_cnt else 0 end) platform_cspu_imp_cnt
     ,sum(case when b.model_id is not null then order_cnt else 0 end) winner_cspu_order_cnt
     ,sum(case when c.model_id is not null then order_cnt else 0 end) cheapest_cspu_order_cnt
     ,sum(case when b.model_id is not null or c.model_id is not null then order_cnt else 0 end) platform_cspu_order_cnt
from traffic_exp_aggr_${grass_region_without_quote} a
left join winner_cspu_model_list_${grass_region_without_quote} b
on a.local_hour = b.local_hour
and a.model_id = b.model_id
left join cheapest_cspu_model_list_${grass_region_without_quote} c
on a.local_hour = c.local_hour
and a.model_id = c.model_id
left join winner_cspu_item_list_${grass_region_without_quote} d
on a.local_hour = d.local_hour
and a.item_id = d.item_id
left join cheapest_cspu_item_list_${grass_region_without_quote} e
on a.local_hour = e.local_hour
and a.item_id = e.item_id
group by grouping sets(
    (a.local_hour,exp_group_id,is_item_card,is_ads,mapping_general),
    (a.local_hour,exp_group_id,is_ads,mapping_general),
    (a.local_hour,exp_group_id,is_item_card,mapping_general),
    (a.local_hour,exp_group_id,mapping_general)
    )
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW scene_995_threshold_${grass_region_without_quote} as
SELECT
    *
FROM srdi_mart.dws_sr_data_warehouse_tc_scene_995_threshold_1d
WHERE grass_region IN (${grass_region}) AND local_date = ${local_date}
;

--sql_divide_splitter--
CREATE TEMPORARY VIEW scene_data_step1_${grass_region_without_quote} as
SELECT exp_group_id
     ,user_id
     ,is_item_card
     ,is_ads
     ,mapping_general
     ,sum(imp_cnt) imp_cnt
     ,sum(click_cnt) click_cnt
     ,sum(order_cnt) order_cnt
     ,sum(gmv) gmv
     ,sum(pc2_gmv) pc2_gmv
     ,coalesce(sum(gmv)/sum(order_cnt),0) as gpo
from traffic_exp_${grass_region_without_quote}
GROUP BY 1,2,3,4,5
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW scene_data_${grass_region_without_quote} as
select exp_group_id
     ,if(grouping(a.is_item_card) = 1, '__ALL__', a.is_item_card) is_item_card
     ,if(grouping(a.is_ads) = 1, '__ALL__', a.is_ads) is_ads
     ,a.mapping_general
     ,count(distinct case when imp_cnt>0 then user_id end) scene_imp_uv_1d
     ,sum(imp_cnt) scene_imp_cnt_1d
     ,sum(order_cnt) scene_order_cnt_1d
     ,sum(if(gpo<=gpo_pct,gmv,0)) scene_gmv_995_1d
     ,sum(pc2_gmv) scene_pc2_gmv_1d
     ,sum(gmv) scene_gmv_1d
from scene_data_step1_${grass_region_without_quote} a
left join scene_995_threshold_${grass_region_without_quote} b
on a.is_ads = b.is_ads
and a.is_item_card = b.is_item_card
and a.mapping_general = b.mapping_general
GROUP BY GROUPING SETS (
    (exp_group_id,a.is_item_card,a.is_ads,a.mapping_general),
    (exp_group_id,a.is_ads,a.mapping_general),
    (exp_group_id,a.is_item_card,a.mapping_general),
    (exp_group_id,a.mapping_general)
    )
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW ads_raw_step1_${grass_region_without_quote} as
select
    user_id
     ,expenditure_amt_usd as ads_revenue_usd
     ,c.traffic_type as common_feature
from mp_paidads.dwd_advertise_performance_di__reg_s0_live a
    left join (
    select
    entrance
        ,max(traffic_type) as traffic_type
    from mp_paidads.dim_entry_point_mapping_v2
    group by 1
    ) as c on a.entrance = c.entrance
where grass_region in (${grass_region}) and grass_date=${local_date} and tz_type='local'
  and c.traffic_type in ('Search','You May Also Like','Daily Discover','Post Purchase')
;
--sql_divide_splitter--

