    user_id
     ,common_feature
     ,sum(ads_revenue_usd) as ads_revenue_usd
from ads_raw_step1_${grass_region_without_quote}
group by 1,2
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW ads_${grass_region_without_quote} as
select
    user_id
     ,common_feature
     ,ads_revenue_usd
from ads_raw_step2_${grass_region_without_quote}
union all
select
    user_id
     ,'S&R__ALL__' as common_feature
     ,sum(ads_revenue_usd) as ads_revenue_usd
from ads_raw_step2_${grass_region_without_quote}
group by 1,2
union all
select
    user_id
     ,'RCMD' as common_feature
     ,sum(ads_revenue_usd) as ads_revenue_usd
from ads_raw_step2_${grass_region_without_quote}
where common_feature in ('You May Also Like','Daily Discover','Post Purchase')
group by 1,2
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW exp_ads_${grass_region_without_quote} as
SELECT
    exp_group_id
     ,common_feature
     ,sum(ads_revenue_usd) as scene_ads_rev_usd_1d
FROM user_exp_${grass_region_without_quote} a
         left join ads_${grass_region_without_quote} b on a.user_id=b.user_id
GROUP BY 1,2
;
--sql_divide_splitter--

INSERT OVERWRITE TABLE ${schema}.dws_sr_data_warehouse_tc_pb_one_variation_exp_scene_general_upgrade_1d partition (grass_region = ${grass_region},local_date = ${local_date}, local_hour)
select a.exp_group_id
     ,a.is_ads
     ,a.is_item_card
     ,a.mapping_general
     ,shop_scs_type
     ,business_type
     ,coalesce(item_imp_cnt,0) item_imp_cnt
     ,coalesce(item_click_cnt,0) item_click_cnt
     ,coalesce(item_order_cnt,0) item_order_cnt
     ,coalesce(item_gmv,0) item_gmv
     ,coalesce(model_order_cnt,0) model_order_cnt
     ,coalesce(model_gmv,0) model_gmv
     ,null as scene_imp_uv
     ,null as scene_imp_cnt
     ,null as scene_order_cnt
     ,null as scene_gmv_995
     ,null as scene_pc2_gmv
     ,null as scene_ads_rev_usd
     ,coalesce(scene_imp_uv_1d,0) scene_imp_uv_1d
     ,coalesce(scene_imp_cnt_1d,0) scene_imp_cnt_1d
     ,coalesce(scene_order_cnt_1d,0) scene_order_cnt_1d
     ,coalesce(scene_gmv_995_1d,0) scene_gmv_995_1d
     ,coalesce(scene_pc2_gmv_1d,0) scene_pc2_gmv_1d
     ,scene_ads_rev_usd_1d
     ,coalesce(if(business_type in (3,4),winner_cspu_order_cnt,cheapest_cspu_order_cnt),0) cheapest_cspu_order_cnt
     ,coalesce(platform_cspu_order_cnt ,0) platform_cheapest_cspu_order_cnt
     ,coalesce(scene_gmv_1d,0) scene_gmv_1d
     ,coalesce(if(business_type in (3,4),winner_cspu_imp_cnt,cheapest_cspu_imp_cnt),0) cheapest_cspu_imp_cnt
     ,coalesce(platform_cspu_imp_cnt ,0) platform_cheapest_cspu_imp_cnt
     ,a.local_hour
from exp_cheapest_${grass_region_without_quote} a
left join scene_data_${grass_region_without_quote} b
on a.exp_group_id = b.exp_group_id
and a.is_item_card = b.is_item_card
and a.mapping_general = b.mapping_general
and a.is_ads = b.is_ads
left join exp_ads_${grass_region_without_quote} c
on a.exp_group_id = c.exp_group_id
and a.mapping_general = c.common_feature
and a.is_ads = '__ALL__'
and a.is_item_card = '__ALL__'
left join traffic_exp_cspu_${grass_region_without_quote} d
on a.local_hour = d.local_hour
and a.exp_group_id = d.exp_group_id
and a.is_item_card = d.is_item_card
and a.is_ads = d.is_ads
and a.mapping_general = d.mapping_general
;
